// DiagResult describes the checks used to determine whether Touch ID can be
// used by this process.
type DiagResult struct {
	HasCompileSupport       bool
	HasSignature            bool
	HasEntitlements         bool
	PassedLAPolicyTest      bool
	PassedSecureEnclaveTest bool
	IsAvailable             bool
}

// Diag checks whether this process can use Touch ID and reports each check.
func Diag() (*DiagResult, error) {
	return nativeDiag()
}

// IsAvailable returns true if Touch ID is available in the system.
func IsAvailable() bool {
	return native.IsAvailable()
